-- ============================================================
-- PUVELA — GO-LIVE: migration + import 67 sản phẩm (chạy 1 lần)
-- Supabase → SQL Editor → dán CẢ FILE → Ctrl/Cmd+A → Run
-- ============================================================

-- 1) migration: thêm cột items cho orders (để checkout lưu đơn)
alter table orders add column if not exists items jsonb;

-- 2) import catalog (reset + 67 sản phẩm):
-- ============================================================
-- PUVELA — IMPORT CATALOG (67 sản phẩm) từ danh sách của bạn
-- Giá = ước lượng mặt bằng thị trường VN, chỉnh lại theo giá nhập thật.
-- Ảnh = placeholder, thay bằng ảnh thật (Supabase Storage) sau.
-- Chạy trong Supabase SQL Editor SAU khi đã chạy schema.sql.
-- ============================================================

-- RESET: xoá catalog cũ để thay bằng danh sách này (chạy CẢ FILE một lần). An toàn: orders lưu ở orders.items jsonb.
delete from order_items; delete from product_variants; delete from product_collections; delete from products; delete from brands;

-- BRANDS
on conflict do nothing;

-- PRODUCTS
on conflict (slug) do nothing;

-- VARIANTS (Chiết 5ml, Chiết 10ml, Full)

-- PRODUCT ↔ COLLECTION (theo giới tính — để filter Nữ/Nam/Unisex đúng)
on conflict do nothing;